	private static Object term(Value value) {
		Map<String, Object> result = new LinkedHashMap<>();
		if (value instanceof IRI iri) {
			result.put("kind", "iri");
			result.put("value", iri.stringValue());
		} else if (value instanceof BNode bNode) {
			result.put("kind", "bnode");
			result.put("value", bNode.getID());
		} else if (value instanceof Literal literal) {
			result.put("kind", "literal");
			result.put("value", literal.getLabel());
			Optional<String> language = literal.getLanguage();
			language.ifPresent(s -> result.put("language", s));
			if (literal.getBaseDirection() != Literal.BaseDirection.NONE) {
				result.put("direction", literal.getBaseDirection() == Literal.BaseDirection.LTR ? "ltr" : "rtl");
			}
			if (language.isEmpty() && literal.getDatatype() != null) {
				result.put("datatype", literal.getDatatype().stringValue());
			}
		} else if (value instanceof TripleTerm tripleTerm) {
			result.put("kind", "triple");
			result.put("subject", term(tripleTerm.getSubject()));
			result.put("predicate", term(tripleTerm.getPredicate()));
			result.put("object", term(tripleTerm.getObject()));
		} else {
			throw new IllegalArgumentException("Unsupported RDF value in Workbench page data: " + value.getClass());
		}
		return result;
	}

	private static Object packedTerm(Value value) {
		if (value instanceof IRI iri) {
			return new Object[] { 0, iri.stringValue() };
		}
		if (value instanceof BNode blank) {
			return new Object[] { 1, blank.getID() };
		}
		if (value instanceof Literal literal) {
			Optional<String> language = literal.getLanguage();
			if (language.isPresent()) {
				Literal.BaseDirection direction = literal.getBaseDirection();
				return direction != Literal.BaseDirection.NONE
						? new Object[] { 2, literal.getLabel(), null, language.get(),
								direction == Literal.BaseDirection.LTR ? "ltr" : "rtl" }
						: new Object[] { 2, literal.getLabel(), null, language.get() };
			}
			return new Object[] { 2, literal.getLabel(), literal.getDatatype().stringValue() };
		}
		if (value instanceof TripleTerm triple) {
			return new Object[] { 3, packedTerm(triple.getSubject()), packedTerm(triple.getPredicate()),
					packedTerm(triple.getObject()) };
		}
		throw new IllegalArgumentException("Unsupported RDF value in Workbench query data: " + value.getClass());
	}

